INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metal Slug Advance', 'Now you can have all the 2D arcade action of Metal Slug in the palm of your hand, because Metal Slug Advance has arrived on the Game Boy Advance. Through five action-packed missions, you must move out on foot or in slug vehicles across rugged terrain and underwater bases. Your objective is to rescue hostages by destroying enemies and solving strategic puzzles. Completing your missions becomes easier when you collect more than 100 types of E-cards, which enhance your character''s abilities.' FROM games WHERE igdb_id = 1406 ON CONFLICT (game_id, language_code) DO NOTHING;
