INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('silent-hill-4-the-room', 483, '2004-06-17', 72, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2vyk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aru4c.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill 4: The Room', 'Silent Hill 4: The Room is the fourth installment in the Silent Hill survival horror series. The game is similar to the past entries in terms of atmosphere, never letting the player know what''s behind the next corner or down the street. Aside from the traditional third-person-view, there is now a first-person mode which is used to control the main character when he is in his apartment. Objects that can be interacted with are highlighted by eyeball icons. The previous games in the series have mostly been about exploring the town and solving puzzles, but this installment has much more combat involved. There are more enemies in a given area, spread in cramped spaces. The main character mostly uses a standard Silent Hill arsenal of weapons, such as the steel pipe, pistol and a golf club.' FROM games WHERE igdb_id = 483 ON CONFLICT (game_id, language_code) DO NOTHING;
