INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shin Megami Tensei: Nocturne', 'Shin Megami Tensei III: Nocturne Maniax, released in America as Shin Megami Tensei: Nocturne is an expanded game of the original Shin Megami Tensei III: Nocturne released only in Japan. The Maniax expanded game notably added the Labyrinth of Amala, the Fiend boss fights, the True Demon Ending, and featured Dante from the Devil May Cry series.' FROM games WHERE igdb_id = 9669 ON CONFLICT (game_id, language_code) DO NOTHING;
