INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'UEFA Euro 2004: Portugal', 'Soccer game, developed to coincide with the finals of the UEFA EURO 2004 tournament in Portugal (June 2004). In UEFA EURO 2004, gamers can play as any of the 51 European nations as you immerse yourself in the deepest championship mode ever released. Players can arrange and play friendly matches against other nations or play through the tournament going from qualifying, to playoffs and into the finals. In addition to tracking injuries and suspensions, a new dynamic morale system will track players'' morale, which will fluctuate based on individual and team performances and affect player abilities on the field.' FROM games WHERE igdb_id = 925 ON CONFLICT (game_id, language_code) DO NOTHING;
