INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mr. Driller: Drill Spirits', 'Mr. Driller, experienced with the drill, much use his abilities to dig beneath the Earth''s crust in a race to the finish in order to save the day. Dangerous traps await as you dig through the puzzle layout to the goal, and be careful of Mr. Driller''s air supply which can run out quickly. Find the right powerups to increase abilities and air supply while fighting the time clock.' FROM games WHERE igdb_id = 18330 ON CONFLICT (game_id, language_code) DO NOTHING;
