INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('it-s-mr-pants', 6355, '2004-12-07', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co322t.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scaezs.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'It''s Mr. Pants', 'Based on Rare''s off-beat mascot, It''s Mr. Pants is a traditional puzzle game in the Tetris sense where the challenge is to piece together specific shapes of specific colors on a flat playing field grid. The idea is simple: form rectangles of larger than 3x2 to make them disappear from play. The pieces can be rotated in 90 degree variations, important to get these tiles into the littlest slots on the field. You can''t place same colors on top of each other, but you can place other colors on top of already placed shapes to remove them from play. There are three variations: in "Puzzle," the challenge is to remove all shapes from play with the set amount of pieces. In "Wipeout", you''ve got two minutes to remove all shapes from play with an infinite amount of pieces. And in "Marathon," the challenge is to constantly place and remove shapes as long as you can, trying to keep the session alive as the playfield gets eaten away from the outside in.' FROM games WHERE igdb_id = 6355 ON CONFLICT (game_id, language_code) DO NOTHING;
