INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ghost in the Shell: Stand Alone Complex', 'Based on the movie of the same name, Ghost in the Shell: Stand Alone Complex is a fast-action third-person shooter for up to four players. As "Major" Motoko Kusanagi, Batou, and Tachikoma, you can engage enemies in both multiplayer combat and single-player missions. In single-player mode, your missions involve hacking into machines and computers, controlling your enemies'' minds from a distance, and using a variety of weapons to eliminate your enemies. Complete the Story mode to unlock more playable characters, costumes, and additional weapons.' FROM games WHERE igdb_id = 24252 ON CONFLICT (game_id, language_code) DO NOTHING;
