INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fish Tycoon', 'Fish Tycoon is a virtual fish breeding game. The object is to breed and cross breed fish until you find the 7 Magic Fish and solve the genetic puzzle. You will have to buy supplies like meds, eggs and special plants and then sell some of your fish in your virtual pet store. If you have enough money you can buy new supplies and customize your virtual aquarium.' FROM games WHERE igdb_id = 29117 ON CONFLICT (game_id, language_code) DO NOTHING;
