INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Incredibles', 'Superstrength, superspeed, invisibility, and elasticity are all the powers you have to combat evil in The Incredibles. You''ll need them, because your enemies throw bombs, bullets, and lasers at you. Based on the movie from Pixar, The Incredibles tells the story of a family of undercover superheroes that is trying to live a quiet, suburban life but is forced back into action to save the world. As the film''s main characters, you must fight, race, and solve puzzles in more than 18 action-packed levels.' FROM games WHERE igdb_id = 3782 ON CONFLICT (game_id, language_code) DO NOTHING;
