INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Dukes of Hazzard: Return of the General Lee', 'The Dukes of Hazzard: Return of the General Lee is a mission based racing (or driving) game released on the PlayStation 2 and Xbox consoles. The game is based on the popular Dukes of Hazzard television show. It is the fourth game based on this show, and the only one to be made on a sixth generation console. Two Dukes games were released for the PlayStation and one was created for the Atari 2600 but was never officially released.' FROM games WHERE igdb_id = 5818 ON CONFLICT (game_id, language_code) DO NOTHING;
