INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Wars: Battlefront', 'Star Wars: Battlefront is the first in the Star Wars: Battlefront series and is a third/first-person shooter video game based around battles featured in the Star Wars movies. It was developed by Pandemic Studios and LucasArts, and released on September 20, 2004 for Xbox (playable on Xbox 360), PlayStation 2, and PC, the same day as the release of the Star Wars Trilogy (DVD) set. Players can either play Star Wars: Battlefront online, or offline with up to 4 players (on consoles).' FROM games WHERE igdb_id = 141 ON CONFLICT (game_id, language_code) DO NOTHING;
