INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('feeding-frenzy', 3759, '2004-02-11', 55, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co44e5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8kn.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feeding Frenzy', 'Slurp, gulp, and crunch your way all along the Frenzy Coast in Feeding Frenzy! The rules here are simple: Eat anything that''s smaller than you and swim clear of everything else. The more you eat, the bigger you get, and the bigger you get, the closer you come to taking on the fearsome Shark King. Starfish bubbles don''t help you grow, but they’re an easy way to boost your score. Oysters offer up bonus points in the form of pearls, but be quick or the shell could snap shut with you inside! Nibbling on the tail of a patrolling barracuda is a risky way to earn extra points—he can turn on you in an instant. And the jellyfish - well, it''s best to swim clear of them altogether. Did you know that tuna can swim up to 50 miles per hour? Or that a parrot fish can change its gender? Feeding Frenzy includes more than four dozen fascinating fish facts like these - one between each game level.' FROM games WHERE igdb_id = 3759 ON CONFLICT (game_id, language_code) DO NOTHING;
