INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gungrave: Overdose', 'Three years after the events that took place in the original Gungrave, the Corsione family has unleashed the deadly drug SEED upon the populace. Now it''s up to Grave, Spike and Mika to follow the trail of SEED back to its source and eradicate it once and for all.
