INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Feel the Magic: XY/XX', 'Sega makes its debut on the Nintendo DS with Feel the Magic: XY/XX, a stylized adventure rife with wild events. The story follows a man who uses a suave gang of dramatic performers to gain the attention of a beautiful woman. To help him impress the girl, you must guide him through a series of madcap performances, such as defending against raging bulls and blowing out giant candles. The game supports the unique features of the DS, which let you control the main character with a stylus, your voice, and even your breath.' FROM games WHERE igdb_id = 18331 ON CONFLICT (game_id, language_code) DO NOTHING;
