INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WarioWare: Twisted!', 'After accidentally discovering spin technology, Wario reassembles the developers at WarioWare, Inc. to make a new set of wild minigames. WarioWare: Twisted! maintains the fast-paced style of gameplay from the original WarioWare and introduces a new gyro sensor that lets you control the gameplay by rotating the Game Boy Advance SP left and right. The new controls play into more than 200 minigames. Play through them all to unlock souvenirs, such as bonus games, figurines, and instruments.' FROM games WHERE igdb_id = 1704 ON CONFLICT (game_id, language_code) DO NOTHING;
