INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts: Chain of Memories', 'Kingdom Hearts: Chain of Memories is the second game in the Kingdom Hearts series. It is a direct sequel to Kingdom Hearts and exclusive to the Game Boy Advance. It was published by Square Enix and developed by Jupiter, and was released in 2004. Chronologically, it is the third game in the timeline after Kingdom Hearts Birth by Sleep and Kingdom Hearts, and takes place during Kingdom Hearts 358/2 Days.' FROM games WHERE igdb_id = 1220 ON CONFLICT (game_id, language_code) DO NOTHING;
