INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Test Drive: Eve of Destruction', 'Test Drive: Eve of Destruction blends the best elements of racing and demolition and is packed with 25 different events, including Demo Derby, where the last car standing wins; Gauntlet, where the player climbs behind the wheel of a hearse and tries to finish a set number of laps while the rest of the field attempts to stop them; Trailer Race, a new brand of racing event, where players compete while towing various types of trailers and must finish the race with something resembling a trailer still attached. Additionally, Test Drive: Eve of Destruction offers players a selection of more than 30 custom vehicles, a dynamic soundtrack and a split-screen multiplayer mode for up to four players.' FROM games WHERE igdb_id = 6197 ON CONFLICT (game_id, language_code) DO NOTHING;
