INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Athens 2004', 'With Athens 2004, you can capture all the spirit and emotion of the Olympic Games. The game lets you compete in four arcade and eight competition game modes, ranging from Practice to the Official Decathlon and Heptathlon combined events, while choosing one of 64 countries and 800 different characters. See what it''s like to compete in some of the Olympic Games'' most challenging sports, including athletics (track & field), aquatics (swimming), gymnastics, shooting, archery, weightlifting, and equestrian. Participate in such events as hurdles, long jump, pole vault, shot put, and more.' FROM games WHERE igdb_id = 22298 ON CONFLICT (game_id, language_code) DO NOTHING;
