INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Serious Sam: Next Encounter', 'In this installment of the Serious Sam series, Sam takes on a new arch-nemesis "Mini Sam", an evil clone of the hero Sam "Serious" Stone. Mini Sam has taken control of the timelock and is going through time wiping out ancient civilizations - and it is up to Serious Sam to put a stop to him.
