INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('gallop-racer-2004', 20146, '2004-02-19', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6j1v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sctan7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gallop Racer 2004', 'In Gallop Racer 2004 (Also known as "Gallop Racer Lucky 7" in Japan, and "Gallop Racer 2" in Europe and Australia), high-resolution graphics, advanced racing, and a variety of new modes reach to a higher level in digital horse racing fun. Old favorites such as the betting system and the classic season mode will also be back in the new title. Features: Enhanced Revolution Mode. Players will now be able to experience the perfect ride using the "Ability" setting to create an enhanced revolution called the "Big Revolution". Dramatic graphics such as the screen breaking into a million pieces like a mirror will add to the player''s rush once they achieve the "Big Revolution". Affinity of Ability System. A new breeding system that allows the player to produce a maximum of eight original horses at one time. Once created these horses can be used as either the player''s ride of choice or used as a rival''s horse. Increased Camera Angles. Allowing the player to see their horse from every angle during the race will keep their blood pumping. Season Mode. With over 17 characters battling it out for the title of top jockey, the season mode has never been hotter or more intense! New Stages. Various new stages such as competitions against rivals and negotiations with trainers help to create the complete horse racing experience. Improved Graphics. High-resolution textures, enhanced effects, and improved use of shadow and depth of color immerse have been included to make the game look more natural and realistic. More Tracks and Horses. Featuring over 4,000 new horses and 42 tracks.' FROM games WHERE igdb_id = 20146 ON CONFLICT (game_id, language_code) DO NOTHING;
