INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brave-dwarves-back-for-treasures', 73533, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2l84.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8scw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brave Dwarves: Back for Treasures', 'This is not just another fairy tale. It''s a saga about the everlasting battle between good and evil, and you are the main character. Since earliest times the glorious clan of dwarves is standing guard over the subterranean world. And this work is hard and all-important indeed. Only the few know that all the worlds are connected to each other with secret passages. Most of these passages are underground, hidden from strangers'' eyes. A casual traveler enters a cave as a shelter from bad weather, but we know it hides a gate to another world. A gate from where unbidden visitors may come. 
