INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turtle Bay', 'After alien octopuses have taken over several bays in the Caribbean, Amazon and Antarctica, abducting and freezing Kroet''s fellow sea creatures in the process, it is up to the player to stop their spread by propelling Kroet into the octopuses while they are pupating.' FROM games WHERE igdb_id = 79302 ON CONFLICT (game_id, language_code) DO NOTHING;
