INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mobile Suit Gundam: Gundam vs. Zeta Gundam', 'Mobile Suit Gundam: Gundam vs. Zeta Gundam takes place seven years after the end of the devastating One-Year War, with the Titans police force assuming dictatorial powers. As the A.E.U.G. rebel group struggles to defeat the Titans, the heroes and villains of the original Mobile Suit Gundam series find themselves on the same side of this new conflict. You can choose whether to play as a member of the A.E.U.G. or Titans, and strap yourself into one of 31 new mobile suits. Practice your maneuvering skills in single-player story mode or take on a friend in multiplayer battles.' FROM games WHERE igdb_id = 3964 ON CONFLICT (game_id, language_code) DO NOTHING;
