INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Champions of Norrath: Realms of EverQuest', 'An action adventure RPG with a hack and slash (or dungeon crawler) style gameplay. Taking place in the EverQuest world you pick between a variety of classes and races and set off on an adventure that brings you across different lands, multiple dungeons, and tasks you with a multitude of quests to complete while leveling your character, finding new weapons and armour, and learning new abilities as you progress. You can share this adventure with a partner on the couch with co-operative gameplay or jump online.' FROM games WHERE igdb_id = 9813 ON CONFLICT (game_id, language_code) DO NOTHING;
