INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-Zero: GP Legend', 'The F-Zero series grows with new racing circuits, an intense storyline, and multiplayer modes. F-Zero GP Legend lets you take control of one of eight characters, including Captain Falcon, racing star Rick Wheeler, the evil lord Black Shadow, and more. Guide your character through various Grand Prix cups, time trials, and challenges that span multiple planets. In addition to conquering single-player challenges, you can challenge up to three of your friends in multiplayer competitions.' FROM games WHERE igdb_id = 3493 ON CONFLICT (game_id, language_code) DO NOTHING;
