INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'James Bond 007: Everything or Nothing', 'Returning as James Bond is Pierce Brosnan, who will lend his cyberscanned likeness and voice to the character. The rest of the cast will include new Bond girls (Shannon Elizabeth and Heidi Klum) as well as old and new Bond villains. The original script will take players through exciting locales in four continents including the Valley of the Kings in Egypt and the French Quarter in New Orleans.' FROM games WHERE igdb_id = 1644 ON CONFLICT (game_id, language_code) DO NOTHING;
