INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GoldenEye: Rogue Agent', 'GoldenEye: Rogue Agent is a first-person shooter video game developed by EA LA and published by Electronic Arts. The player takes the role of an ex-MI6 agent Jack Hunter, who is recruited by Auric Goldfinger (a member of a powerful unnamed criminal organisation based on Ian Fleming''s SPECTRE) to assassinate his rival Dr. No. Several other characters from the Bond series make appearances throughout the game, including Pussy Galore, Oddjob, Xenia Onatopp and Francisco Scaramanga.
