INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shellshock: Nam ''67', 'ShellShock: Nam ''67 depicts, for the first time in a video game, the true horrors of the Vietnam War. Focusing on one man''s ordeals during one of the most controversial wars of modern times, Shellshock: Nam ''67 dares to go where no other war game has gone. The player assumes the role of a rookie soldier on his first tour of duty, as he experiences all the fear, chaos and atrocities of the Vietnam War.' FROM games WHERE igdb_id = 1870 ON CONFLICT (game_id, language_code) DO NOTHING;
