INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PangYa', 'PangYa is a fantasy-themed online multiplayer golf game where players compete on vibrant, imaginative courses. With anime-inspired characters, customizable outfits, and special power shots, it offers a fun twist on traditional golf. Players can enjoy various game modes, including tournaments, team battles, and seasonal events, all while earning in-game currency (Pang) to unlock new gear. Social features like guilds and mini-games add to the community experience, making PangYa an exciting blend of golf, fantasy, and strategy.' FROM games WHERE igdb_id = 22593 ON CONFLICT (game_id, language_code) DO NOTHING;
