INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: Trails in the Sky', 'The Legend of Heroes: Trails in the Sky is the first installment in the main Trails series, serving as the beginning to the Liberl arc and the series as a whole. The game follows protagonists Estelle Bright and her adopted brother Joshua, who journey through the country of Liberl to train to become senior Bracers, members of a non-government multinational organization that acts to keep the peace and protect civilians.
