INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('leisure-suit-larry-kuhle-drinks-und-heisse-girls', 85980, '2004-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2uxy.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leisure Suit Larry: Kühle Drinks und Heiße Girls', 'Leisure Suit Larry: Kühle Drinks und heiße Girls is a promotional teaser for Leisure Suit Larry: Magna Cum Laude, the eighth main entry in the Leisure Suit Larry series. This Macromedia Flash-based compilation features three mini-games that showcase the franchise''s trademark adult humor and themes. In Bar Wars, players serve attractive women while avoiding less appealing customers. Nightwatch challenges players to balance duties as a hostel night watchman with romantic pursuits. Babewatch casts players as a lifeguard, juggling beach safety responsibilities and potential romantic encounters. These mini-games offer a glimpse into the humor and gameplay style of Magna Cum Laude, maintaining the series'' focus on comedic sexual situations and Larry''s perpetual quest for romance while introducing new scenarios and mechanics.' FROM games WHERE igdb_id = 85980 ON CONFLICT (game_id, language_code) DO NOTHING;
