INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leisure Suit Larry: Magna Cum Laude - Uncut and Uncensored', 'With gorgeous co-eds everywhere, college dweeb Larry Lovage is chasing around more than his diploma. He''s trying to live up to the legend of his uncle, Larry Laffer, everyone''s favourite polyester playboy. Larry Lovage is a typical college student. He lives in a dorm, has a crush on his biology professor, and goes to bars with his buddies. But when a TV dating show comes to campus, Larry gets a chance for national sexposure. If he can show that he can make any girl on campus swoon, he will become a campus legend.' FROM games WHERE igdb_id = 81729 ON CONFLICT (game_id, language_code) DO NOTHING;
