INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nexus-the-jupiter-incident--1', 14828, '2004-11-05', 73, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co256f.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21oo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nexus: The Jupiter Incident', 'At the dawn of the 22nd century, the conquest of space and the colonization of the solar system is being monopolized by several huge and ambitious mega-corporations. Although extremely delicate and vulnerable, a balance is maintained by these companies. At the very edge of the solar system the companies make a discovery which will shift the technological advantage and upset the balance. And so a new conflict is born: "The Jupiter Incident".
