INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Ops: Red Mercury', 'Shadow Ops: Red Mercury is an action-oriented first person shooter based on modern military weapons, equipment and tactics, although presented as a "blockbuster action movie" rather than a hardcore realistic military simulation. Players proceed through linear levels while battling terrorists and hostile enemy soldiers in locations spanning all around the globe, such as Syria and France, using an assortment of modern firearms.' FROM games WHERE igdb_id = 6043 ON CONFLICT (game_id, language_code) DO NOTHING;
