INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xpand Rally', 'Xpand Rally is a breathtaking game that gives you the true to life experience of driving powerful rally cars amidst photorealistic sceneries. Realistic weather effects, rolling hills, and animated scenery all add to game''s visual perfection. Xpand Rally also features highly detailed models of modern rally cars and handling physics developed with the help of rally sport professionals which further enhance the realism of driving experience.' FROM games WHERE igdb_id = 8034 ON CONFLICT (game_id, language_code) DO NOTHING;
