INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Bugs', 'Cosmic Bugs (previously titled Cosmo Bots) is an action-puzzle PC game developed by Retro64. The game was initially released on November 11, 2004, and later republished through PopCap Games in 2007, rebranded as Cosmic Bugs. It was available for download until the client shut down in 2013.' FROM games WHERE igdb_id = 72161 ON CONFLICT (game_id, language_code) DO NOTHING;
