INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ESPN NFL 2K5', 'ESPN NFL 2K5 is an American football video game developed by Visual Concepts for the PlayStation 2 and Xbox consoles. Published by Sega Sports and the Sega Corporation, it is the sixth installment of the NFL 2K series and the last to use official NFL licensing until an unnamed sequel is released in 2021. Gameplay is presented as a live ESPN television broadcast and features the voices and digital likenesses of multiple ESPN on-air personalities.
