INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blinx 2: Masters of Time and Space', 'Blinx 2: Masters of Time & Space continues the adventures of Blinx, a heroic cat with the ability to make time slow, fast-forward, rewind, or stop. In this sequel, Blinx and his squad of tough, agile cats use their time-control powers to battle menacing time monsters, outmaneuver the criminal pig gang, and discover why time is disappearing. You can play as Blinx or his rivals--the sneaky pigs--who are equipped with the ability to morph and control space.' FROM games WHERE igdb_id = 5752 ON CONFLICT (game_id, language_code) DO NOTHING;
