INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SpongeBob SquarePants Bowling', 'SpongeBob SquarePants Bowling is a casual, timing‑based bowling game. Bowl as characters from Bikini Bottom, each with distinct power, aim, and spin attributes. Use simple meters for placement, power, and spin, and tackle practice, pass‑and‑play, or tournament modes.' FROM games WHERE igdb_id = 23599 ON CONFLICT (game_id, language_code) DO NOTHING;
