INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-Gi-Oh! The Dawn of Destiny', 'Yu-Gi-Oh! The Dawn of Destiny is a strategy video game with over 1,000 Yu-Gi-Oh! cards that integrates the trading card gameplay and rules with 3D monster battles. Players engage in strategic duels against AI opponents, exploring various game modes including Link Duel and Triple Duel modes, which offer fresh challenges and test players'' skills against multiple opponents simultaneously.' FROM games WHERE igdb_id = 6257 ON CONFLICT (game_id, language_code) DO NOTHING;
