INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Syphon Filter: The Omega Strain', 'Syphon Filter: The Omega Strain is a third-person shooter developed by Bend Studio and published by Sony Computer Entertainment. Released in May 2004 for the PlayStation 2, it is the fourth instalment in the Syphon Filter series. The game follows a global bioterrorism crisis, and players assume the role of a new recruit in Gabe Logan’s agency, tasked with stopping the spread of the deadly Omega Strain virus.' FROM games WHERE igdb_id = 20185 ON CONFLICT (game_id, language_code) DO NOTHING;
