INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yoshi-topsy-turvy', 49212, '2004-04-22', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co47kd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar220m.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yoshi Topsy-Turvy', 'In Yoshi Topsy-Turvy, Yoshi Island has been turned into a picture book. Yoshi will not stand for this outlandish attempt at flattening his world, and he heads off on an adventure to return things back to their original state. To help in on his quest, a group of spirits who like to surprise people give Yoshi the ability to rotate the world to his liking. The big catch with Yoshi Topsy-Turvy is its use of a motion sensor, similar to the one set to be featured in the second Wario Ware GBA game. The game cartridge includes a built in motion sensor which detects how you move the GBA system. By turning the system, you make the world rotate. A meter on the upper right corner of the screen shows which way the system is being held at any time. Rotate the system to help Yoshi stay on the path and make it past perils and through the varied stages.
