INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Front Ausf.B', 'You are sent out to the North African front of WWII where hell has broken loose. As the commander of a tank squadron you are going to need all your nerves, wits and strategy to succeed in your mission and gain victory.' FROM games WHERE igdb_id = 22571 ON CONFLICT (game_id, language_code) DO NOTHING;
