INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mlb-slugfest-loaded', 23537, '2004-07-24', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5dgn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/waetnsbszbavb9njms3g.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB SlugFest: Loaded', 'Action baseball game, featuring Midway''s classic fast and furious gameplay with beanballs, hard tags, and over-the-top animations. SlugFest features some of the greatest baseball players with the addition of over-the-top abilities, including turbo-speed running, highlight reel-worthy fielding, Earth-shaking collisions and the ability to catch fire and turbo charge the game action. All-new gameplay features add customizable replay, exploding Scoreboards, and updated MLB team rosters. You can also take your coaching skills, players and/or teams online, voice chat with other players, and access an on-screen sports Ticker Tape. Also features an Online Tournament Mode and a soundtrack featuring Ivory Wire, Buckfast Superbee and Flipswitch.' FROM games WHERE igdb_id = 23537 ON CONFLICT (game_id, language_code) DO NOTHING;
