INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack the Ripper', 'Since August 31, 1888, the identity of Jack the Ripper has eluded criminologists. Using the actual clues and evidence assembled from years of painstaking research, now you can solve the mystery. Travel around authentic Victorian London locations in search of clues and interview over one hundred actual persons and suspects. Only you can stop Jack before he strikes again.' FROM games WHERE igdb_id = 20410 ON CONFLICT (game_id, language_code) DO NOTHING;
