INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Urbz: Sims in the City', 'The Sims have moved to the City where there''s always action and where reputation means everything. In the Urbz: Sims in the City, you can go to work at such locations as the Sushi Bar, Chop Shop, or Bootleg Fireworks, Inc. Success at work brings promotions, access to new power socials, and gear to influence your new lifestyle. Flaunt your attitude by styling your Urbz, and then cross the velvet ropes of an uptown night club, or explore the subway to earn new skills and items.' FROM games WHERE igdb_id = 2158 ON CONFLICT (game_id, language_code) DO NOTHING;
