INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('autobahn-raser-das-spiel-zum-film', 144385, '2004-02-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ung.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Autobahn Raser: Das Spiel zum Film', 'Autobahn Raser: Das Spiel zum Film is the game based on the movie Autobahn Raser which is based on the Autobahn Raser game series. Like usual the player races through courses based on real German cities, this time Munich, Berlin, Hamburg and Cologne. There are four playing modes: racing against opponents, racing against the clock, police chases and a campaign which has nothing to do with the movie. The difference to the regular races is that the player sometimes has to ram stolen car dealers off the road.The connection to the movie are film sequences, biographies of the actors, the original soundtrack and similar cars.' FROM games WHERE igdb_id = 144385 ON CONFLICT (game_id, language_code) DO NOTHING;
