INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killzone', 'Killzone is a sci-fi-themed first-person shooter. The game''s stand-out feature is the ability to control any of the four different protagonists, each with his or her own strengths and weaknesses. Up to sixteen players could compete in the online multiplayer portion, which includes eight maps and six modes: Deathmatch, Team Deathmatch, Assault, Defend and Destroy, Supply Drop, and Domination. The online servers of the game have now been closed down.' FROM games WHERE igdb_id = 1865 ON CONFLICT (game_id, language_code) DO NOTHING;
