INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MTV Music Generator 3: This is the Remix', 'Create and sample original music tracks, and remix some songs from today''s hip-hop and electronica artists. Songs include OutKast''s "The Way U Move," Snoop Dogg''s "From Tha Chuuuch To Da Palace," Sean Paul''s "Get Busy," Fabolous'' "This Is My Party," and Carl Cox''s "Katja." You can even combine samples from your own music collection to bring your favorite artists together in a remixed track. With a full-featured Studio Mode--including an editing bay of riffs, beats, bass lines, and vocals--aspiring DJs, producers, and music aficionados alike can easily assemble professional material in a matter of minutes.' FROM games WHERE igdb_id = 24139 ON CONFLICT (game_id, language_code) DO NOTHING;
