INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechAssault 2: Lone Wolf', 'MechAssault 2: Lone Wolf continues the destruction, intense combat, and online play introduced by the first MechAssault game. Set in the 31st century, the game lets you encounter new experiences in the expansive BattleTech world. Choose from a variety of weapons and vehicles--from the stealthy Raptor mech to the mech-jacking BattleArmor--all equipped with different weapon configurations and artillery. Embark on the new single-player campaign, or test your teamwork skills in the online multiplayer arena.' FROM games WHERE igdb_id = 5911 ON CONFLICT (game_id, language_code) DO NOTHING;
